import pathlib
p = pathlib.Path('weathergpt_data/specialist_tasks.py')
t = p.read_text()
assert t.count("    points=None\n    place=(plan.get('places') or [None])[0]\n    if place and len(plan.get('places') or [])==1 and not (resolved or {}).get(place.get('name')):\n        candidates=engine.gazetteer.search(place.get('name') or '',place.get('state') or '',place.get('district') or '')\n        if len(candidates)>1 and all(candidate.get('match_type')!='approximate_name_requires_confirmation' for candidate in candidates):") == 1, 'specialist anchor'
t = t.replace("    points=None\n    place=(plan.get('places') or [None])[0]\n    if place and len(plan.get('places') or [])==1 and not (resolved or {}).get(place.get('name')):\n        candidates=engine.gazetteer.search(place.get('name') or '',place.get('state') or '',place.get('district') or '')\n        if len(candidates)>1 and all(candidate.get('match_type')!='approximate_name_requires_confirmation' for candidate in candidates):", "    points=None\n    place=(plan.get('places') or [None])[0]\n    if place and len(plan.get('places') or [])==1 and not (resolved or {}).get(place.get('name')):\n        candidates=engine.gazetteer.search(place.get('name') or '',place.get('state') or '',place.get('district') or '')\n        from .gazetteer import preferred_match as _preferred\n        ranked,_why=_preferred(candidates)\n        if ranked is not None:\n            # A candidate outranks the others on its own merits; the product probe is not used to\n            # overturn a rank, only to settle a genuine tie.\n            candidates=[]\n        if len(candidates)>1 and all(candidate.get('match_type')!='approximate_name_requires_confirmation' for candidate in candidates):", 1)
p.write_text(t)
print('specialist probe gated on a tie')